def gen(rng):
    def fmt(ttl, ops):
        return f"{len(ops)} {ttl}\n" + '\n'.join(ops)
    def word(i, length):
        s = []
        for _ in range(length):
            s.append(chr(97 + i % 26))
            i //= 26
        return ''.join(s)
    tests = [
        fmt(1, ['TOTAL 0']),
        fmt(5, ['PUT 1 a', 'PUT 2 b', 'PUT 3 a', 'COUNT 4 a', 'TOTAL 5', 'TOTAL 6', 'COUNT 7 a', 'TOTAL 8']),
        fmt(10, ['PUT 0 x', 'PUT 1 y', 'PUT 1 x', 'REMOVE 2 x', 'COUNT 3 x', 'PUT 4 x', 'TOTAL 5']),
        fmt(3, ['PUT 5 k', 'PUT 5 k', 'PUT 5 k', 'COUNT 5 k', 'COUNT 7 k', 'COUNT 8 k', 'TOTAL 8']),
        fmt(1, ['PUT 4 z', 'COUNT 4 z', 'COUNT 5 z', 'PUT 5 z', 'TOTAL 5']),
        fmt(10**9, ['PUT 0 a', 'PUT 1000000000 b', 'TOTAL 1000000000', 'COUNT 1000000000 a']),
        fmt(4, ['PUT 1 a', 'REMOVE 1 a', 'PUT 1 a', 'COUNT 2 a', 'REMOVE 4 a', 'COUNT 5 a', 'TOTAL 5']),
        fmt(6, ['REMOVE 0 a', 'COUNT 0 a']),
    ]
    keys3 = ['a', 'b', 'c']
    for _ in range(40):
        q = rng.randint(1, 25)
        ttl = rng.randint(1, 8)
        t = rng.randint(0, 3)
        ops = []
        for _ in range(q):
            t += rng.choice([0, 0, 1, 1, 2, 3])
            r = rng.random()
            k = rng.choice(keys3)
            if r < 0.4:
                ops.append(f'PUT {t} {k}')
            elif r < 0.6:
                ops.append(f'COUNT {t} {k}')
            elif r < 0.8:
                ops.append(f'TOTAL {t}')
            else:
                ops.append(f'REMOVE {t} {k}')
        ops.append(f'TOTAL {t + rng.randint(0, 3)}')
        tests.append(fmt(ttl, ops))
    def big(q, ttl, pool, step, weights):
        t = 0
        ops = []
        w_put, w_cnt, w_tot, w_rem = weights
        for _ in range(q):
            t += rng.randint(0, step)
            r = rng.random() * (w_put + w_cnt + w_tot + w_rem)
            k = pool[rng.randrange(len(pool))]
            if r < w_put:
                ops.append(f'PUT {t} {k}')
            elif r < w_put + w_cnt:
                ops.append(f'COUNT {t} {k}')
            elif r < w_put + w_cnt + w_tot:
                ops.append(f'TOTAL {t}')
            else:
                ops.append(f'REMOVE {t} {k}')
        assert t <= 10**9
        return fmt(ttl, ops)
    pool = [word(rng.randrange(26**6), 6) for _ in range(30000)]
    tests.append(big(100000, 10**9, pool, 19000, (60, 20, 15, 5)))
    tests.append(big(100000, 200000, pool, 10, (50, 20, 25, 5)))
    tests.append(big(100000, 5000, pool[:50], 3, (45, 25, 25, 5)))
    tests.append(big(100000, 1, pool, 2, (50, 20, 25, 5)))
    tests.append(big(100000, 10**9, pool[:1], 1000, (70, 15, 15, 0)))
    return tests
